content.text:
{
  "name": "文件项目存储系统",
  "name_en": "File Project Storage System",
  "manufacturer": "",
  "description": "一种基于文件的项目持久化存储组件，用于在实验数据工作流中保存项目属性、数据项关系以及相关数据文件路径，支持实验项目的数据组织、读取与长期归档。",
  "description_en": "A file-based project persistence component used in laboratory data workflows to store project properties, data-item relationships, and related data file paths, supporting experiment data organization, loading, and long-term archiving.",
  "actions": [
    {
      "action_name": "auto-load_properties",
      "description": "加载项目存储属性并解析可用的数据文件夹路径。",
      "description_en": "Load project storage properties and resolve an available data folder path."
    },
    {
      "action_name": "auto-project_path",
      "description": "获取项目存储路径。",
      "description_en": "Get the project storage path."
    },
    {
      "action_name": "auto-get_identifier",
      "description": "获取项目存储系统标识符。",
      "description_en": "Get the project storage system identifier."
    },
    {
      "action_name": "auto-encode",
      "description": "将项目存储信息编码为可持久化表示。",
      "description_en": "Encode the project storage information into a persistent representation."
    }
  ],
  "tag_hints": [
    "file-based persistence",
    "project data storage",
    "laboratory data management",
    "data archiving",
    "metadata storage",
    "project file organization"
  ]
}

